"""Deterministic multi-topology constrained constructor for 26 circles."""
import numpy as np
from scipy.optimize import minimize


def _make_seed(rows, variant):
    ys = np.array([.105, .302, .500, .698, .895], dtype=float)
    if variant & 1:
        ys = ys[::-1].copy()
    if variant & 2:
        ys += np.array([-.006, .004, 0., -.004, .006])
    out = []
    for k, m in enumerate(rows):
        if m == 6:
            lo, hi = .075, .925
        elif m == 5:
            lo, hi = .095, .905
        else:
            lo, hi = .18, .82
        x = np.linspace(lo, hi, m)
        if (k + variant) & 1:
            x += .5 * (x[1] - x[0])
        if variant & 2:
            x += (.004 if k % 2 else -.004)
        out.extend(zip(x, np.full(m, ys[k])))
    return np.asarray(out, dtype=float)


def _initial_radii(p):
    n = len(p)
    d = np.sqrt(np.maximum(((p[:, None] - p[None, :]) ** 2).sum(2), 1e-30))
    np.fill_diagonal(d, np.inf)
    b = np.minimum.reduce((p[:, 0], p[:, 1], 1-p[:, 0], 1-p[:, 1]))
    r = np.minimum(b, .14)
    for _ in range(45):
        for i in range(n):
            r[i] = max(1e-10, min(b[i], np.min(d[i] - r)))
    return np.maximum(r * (1 - 2e-5), 1e-9)


def construct_packing():
    n = 26
    ii, jj = np.triu_indices(n, 1)

    def unpack(z):
        return z[:2*n].reshape(n, 2), z[2*n:]

    def cons(z, margin):
        p, r = unpack(z)
        q = p[ii] - p[jj]
        d = np.sqrt(np.maximum((q*q).sum(axis=1), 1e-24))
        return np.r_[p[:, 0]-r, p[:, 1]-r,
                     1-p[:, 0]-r, 1-p[:, 1]-r,
                     d-r[ii]-r[jj]-margin]

    bounds = [(1e-5, 1-1e-5)]*(2*n) + [(1e-9, .25)]*n
    topologies = ((5,5,6,5,5), (4,6,6,6,4),
                  (5,6,5,6,4), (4,6,5,6,5))
    best = None
    best_sum = -np.inf

    for ti, rows in enumerate(topologies):
        for v in range(2):
            p = _make_seed(rows, ti*2+v)
            r = _initial_radii(p)
            z = np.r_[p.ravel(), r]
            good = True
            for margin, iters in ((2e-5, 190), (2e-6, 190), (2e-8, 130)):
                res = minimize(
                    lambda q: -float(np.sum(q[2*n:])),
                    z, method="SLSQP", bounds=bounds,
                    constraints={"type": "ineq",
                                 "fun": lambda q, m=margin: cons(q, m)},
                    options={"maxiter": iters, "ftol": 3e-9,
                             "disp": False})
                if not np.all(np.isfinite(res.x)):
                    good = False
                    break
                z = res.x
            if not good or np.any(cons(z, 0.) < -3e-7):
                continue
            p1, r1 = unpack(z)
            val = float(r1.sum())
            if val > best_sum:
                best_sum = val
                best = (p1.copy(), r1.copy())

    if best is None:
        p = _make_seed((5,5,6,5,5), 0)
        r = _initial_radii(p)
        return p, r, float(r.sum())

    p, r = best
    z = np.r_[p.ravel(), r]
    res = minimize(
        lambda q: -float(np.sum(q[2*n:])), z, method="SLSQP",
        bounds=bounds,
        constraints={"type": "ineq", "fun": lambda q: cons(q, 1e-8)},
        options={"maxiter": 100, "ftol": 1e-10, "disp": False})
    if np.all(np.isfinite(res.x)) and np.all(cons(res.x, 0.) >= -2e-7):
        pp, rr = unpack(res.x)
        if rr.sum() >= r.sum():
            p, r = pp, rr

    p = np.clip(p, 1e-8, 1-1e-8)
    b = np.minimum.reduce((p[:,0], p[:,1], 1-p[:,0], 1-p[:,1]))
    r = np.minimum(r, b)
    d = np.sqrt(np.maximum(((p[:,None]-p[None,:])**2).sum(2), 1e-30))
    np.fill_diagonal(d, np.inf)
    for i in range(n):
        for j in range(i+1, n):
            excess = r[i] + r[j] + 2e-9 - d[i,j]
            if excess > 0:
                if r[i] >= r[j]:
                    r[i] = max(1e-10, r[i]-excess)
                else:
                    r[j] = max(1e-10, r[j]-excess)
    r *= 1 - 1e-8
    return p, r, float(r.sum())


def compute_max_radii(centers):
    n = centers.shape[0]
    r = np.minimum.reduce((centers[:,0], centers[:,1],
                           1-centers[:,0], 1-centers[:,1]))
    d = np.sqrt(np.maximum(((centers[:,None]-centers[None,:])**2).sum(2), 1e-30))
    np.fill_diagonal(d, np.inf)
    for i in range(n):
        for j in range(i+1,n):
            if r[i]+r[j] > d[i,j]:
                q = d[i,j]/(r[i]+r[j])
                r[i] *= q
                r[j] *= q
    return r


def run_packing():
    return construct_packing()


def visualize(centers, radii):
    import matplotlib.pyplot as plt
    from matplotlib.patches import Circle
    fig, ax = plt.subplots(figsize=(8,8))
    ax.set_xlim(0,1); ax.set_ylim(0,1)
    ax.set_aspect("equal"); ax.grid(True)
    for i,(c,r) in enumerate(zip(centers,radii)):
        ax.add_patch(Circle(c,r,alpha=.5))
        ax.text(c[0],c[1],str(i),ha="center",va="center")
    plt.show()


if __name__ == "__main__":
    c,r,s = run_packing()
    print("Sum of radii:", s)

